import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ __launch_bounds__(256) void tanh_kernel_vec4(const float4* __restrict__ in, float4* __restrict__ out, int64_t n4) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    // Simple grid-stride loop (no manual unroll) reduces register pressure
    // and avoids load imbalance between warps near the tail, improving
    // achieved occupancy for this memory-bound kernel.
    // Relaxed launch_bounds min-blocks hint (was 8) so the compiler is not
    // forced into a tight <=32 reg/thread budget, which previously caused
    // register pressure / spilling and reduced achieved occupancy despite
    // a reported 100% theoretical occupancy.
    for (int64_t i = idx; i < n4; i += stride) {
        float4 v = in[i];
        v.x = tanhf(v.x);
        v.y = tanhf(v.y);
        v.z = tanhf(v.z);
        v.w = tanhf(v.w);
        out[i] = v;
    }
}
__global__ __launch_bounds__(256, 8) void tanh_kernel_scalar(const float* __restrict__ in, float* __restrict__ out, int64_t n) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    int64_t i = idx;
    for (; i + stride < n; i += 2 * stride) {
        float v0 = in[i];
        float v1 = in[i + stride];
        out[i] = tanhf(v0);
        out[i + stride] = tanhf(v1);
    }
    for (; i < n; i += stride) {
        out[i] = tanhf(in[i]);
    }
}
torch::Tensor tanh_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);
    int64_t n = x_contig.numel();

    const int threads = 256;

    if (n % 4 == 0) {
        int64_t n4 = n / 4;
        int device = 0;
        cudaGetDevice(&device);
        int sm_count = 1;
        cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
        int64_t blocks64 = (n4 + threads - 1) / threads;
        // Cap grid size to a modest multiple of SM count so the grid-stride
        // loop performs the sweep with fewer, better load-balanced blocks,
        // reducing tail imbalance and improving achieved occupancy.
        int64_t max_blocks = (int64_t)sm_count * 32;
        if (blocks64 > max_blocks) blocks64 = max_blocks;
        int blocks = (blocks64 > 2147483647LL) ? 2147483647 : (int)blocks64;
        if (blocks < 1) blocks = 1;
        tanh_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x_contig.data_ptr<float>()),
            reinterpret_cast<float4*>(out.data_ptr<float>()),
            n4
        );
    } else {
        int64_t blocks64 = (n + threads - 1) / threads;
        int blocks = (blocks64 > 2147483647LL) ? 2147483647 : (int)blocks64;
        if (blocks < 1) blocks = 1;
        tanh_kernel_scalar<<<blocks, threads>>>(
            x_contig.data_ptr<float>(),
            out.data_ptr<float>(),
            n
        );
    }

    return out;
}
"""

cpp_source = "torch::Tensor tanh_cuda(torch::Tensor x);"

tanh_module = load_inline(
    name="tanh_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["tanh_cuda"],
    extra_cuda_cflags=["-use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a Tanh activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.tanh_op = tanh_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.tanh_op.tanh_cuda(x)


